@@ -0,0 +1,31 @@
+// Sites: the kitchens Larder serves. Every location belongs to one site;
+// batches belong to the site of their location. Items, suppliers, recipes
+// and dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site of a request that names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in the stored order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Ids of the locations of a site, or of every site when `site` is null. */
+export function locationIds(store, site) {
+  return new Set(store.data.locations.filter((l) => site === null || l.site === site).map((l) => l.id));
+}
+
+/** One location of a site, or AppError unknown_location. */
+export function getLocation(store, id, site = DEFAULT_SITE) {
+  const location = store.data.locations.find((l) => l.id === id && l.site === site);
+  if (!location) throw new AppError("unknown_location", { id });
+  return location;
+}
