--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,63 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 2, lines: [{ itemId: 2, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  return handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: annex, body: { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+}
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("stock, batches and reports only see the request's site", async () => {
+  const { handle } = app();
+  const empty = await handle({ path: "/items", headers: annex });
+  assert.ok(empty.body.every((i) => i.onHand === 0));
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+
+  const received = await stockAnnex(handle);
+  assert.equal(received.status, 200);
+  const [batch] = received.body.batches;
+  assert.equal((await handle({ path: "/items/2", headers: annex })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  assert.deepEqual((await handle({ path: "/alerts", headers: annex })).body.expiring.map((b) => b.id), [batch.id]);
+  assert.ok(!(await handle({ path: "/alerts" })).body.expiring.some((b) => b.id === batch.id));
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 387);
+});
+
+test("a location of another site cannot be used", async () => {
+  const { handle } = app();
+  const take = await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } });
+  assert.equal(take.status, 400);
+  assert.equal(take.body.error.code, "unknown_location");
+  const main = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${main.id}/finish`, headers: annex })).status, 404);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", headers: annex, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("the nightly job checks every site", async () => {
+  const { handle, store } = app();
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const keys = store.data.outbox.map((m) => m.key);
+  assert.ok(!keys.includes("low:2026-10-28"));
+  assert.ok(keys.includes("low:2026-10-28:annex"));
+});
